<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Visualizer</title>
    <style>
        body {
            background-color: #121212;
            color: #e0e0e0;
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #controls {
            margin-bottom: 20px;
            display: flex;
            gap: 10px;
        }

        button {
            background-color: #333;
            color: white;
            border: 1px solid #555;
            padding: 8px 16px;
            cursor: pointer;
            font-size: 14px;
            transition: background 0.2s;
        }

        button:hover {
            background-color: #444;
        }

        button:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        #bars {
            display: flex;
            align-items: flex-end;
            justify-content: center;
            width: 80vw;
            height: 60vh;
            gap: 2px;
            border-bottom: 2px solid #444;
        }

        .bar {
            background-color: #4caf50;
            width: 100%;
            transition: height 0.1s ease, background-color 0.1s ease;
        }

        .bar.comparing {
            background-color: #ffeb3b;
        }
    </style>
</head>
<body>

    <div id="controls">
        <button id="shuffle">Shuffle</button>
        <button id="sort">Sort</button>
        <button id="reset">Reset</button>
    </div>
    <div id="bars"></div>

    <script>
        (function() {
            let data = [];
            let i = 0;
            let j = 0;
            let isSorting = false;
            let animationFrame = null;

            const barsContainer = document.getElementById('bars');

            function render() {
                barsContainer.innerHTML = '';
                if (data.length === 0) return;

                const maxVal = Math.max(...data);
                data.forEach((val, idx) => {
                    const bar = document.createElement('div');
                    bar.className = 'bar';
                    // height is proportional to value relative to max
                    const heightPercent = (val / maxVal) * 100;
                    bar.style.height = `${heightPercent}%`;
                    bar.dataset.index = idx;
                    barsContainer.appendChild(bar);
                });
            }

            function checkSorted() {
                for (let k = 0; k < data.length - 1; k++) {
                    if (data[k] > data[k + 1]) return false;
                }
                return true;
            }

            // Programmatic API
            window.viz = {
                array: () => [...data],
                setArray: (a) => {
                    data = [...a];
                    i = 0;
                    j = 0;
                    render();
                },
                sorted: () => checkSorted(),
                sortStep: () => {
                    if (data.length <= 1) return true;

                    // Bubble Sort Step implementation
                    if (i >= data.length) return true;

                    if (j >= data.length - 1 - i) {
                        i++;
                        j = 0;
                        if (i >= data.length) return true;
                    }

                    // Highlight comparison in UI if needed, though not required by API
                    if (data[j] > data[j + 1]) {
                        let temp = data[j];
                        data[j] = data[j + 1];
                        data[j + 1] = temp;
                        render();
                    }

                    j++;
                    return checkSorted();
                }
            };

            // UI logic
            const btnShuffle = document.getElementById('shuffle');
            const btnSort = document.getElementById('sort');
            const btnReset = document.getElementById('reset');

            function generateRandomArray(size = 30) {
                const arr = [];
                for (let k = 0; k < size; k++) {
                    arr.push(Math.floor(Math.random() * 500) + 10);
                }
                return arr;
            }

            function stopAnimation() {
                isSorting = false;
                if (animationFrame) {
                    cancelAnimationFrame(animationFrame);
                    animationFrame = null;
                }
            }

            async function runSort() {
                stopAnimation();
                isSorting = true;
                btnShuffle.disabled = true;
                btnSort.disabled = true;

                const step = () => {
                    if (!isSorting) return;
                    const done = window.viz.sortStep();
                    if (done) {
                        stopAnimation();
                        btnShuffle.disabled = false;
                        btnSort.disabled = true; // Already sorted
                        return;
                    }
                    animationFrame = requestAnimationFrame(() => {
                        // Small timeout to make the animation visible
                        setTimeout(step, 20);
                    });
                };
                step();
            }

            btnShuffle.onclick = () => {
                stopAnimation();
                window.viz.setArray(generateRandomArray());
                btnSort.disabled = false;
            };

            btnSort.onclick = runSort;

            btnReset.onclick = () => {
                stopAnimation();
                window.viz.setArray(generateRandomArray());
                btnSort.disabled = false;
                btnShuffle.disabled = false;
            };

            // Init
            window.viz.setArray(generateRandomArray());
        })();
    </script>
</body>
</html>
